script.segment:
#IF INTR
 #SUBROUTINE EMTDC_XLGATE 'Multiple Input Logic Gate /w Interpolation'
 #STORAGE INTEGER:10
 #LOCAL REAL RVD18_1 18
!
! Multi input, interpolated ~
 #CASE Type {~AND~}{~OR~}{~XOR~}
~ gate
!
      RVD18_1(1)  = ~
 #CASE Inv1 {~$INx1(1)} {~1.0 - $INx1(1)}
      RVD18_1(2)  = ~
 #CASE Inv2 {~$INx2(1)} {~1.0 - $INx2(1)}
      RVD18_1(10) = ~
 #CASE INTR {~0.0} {~$INx1(2)}
      RVD18_1(11) = ~
 #CASE INTR {~0.0} {~$INx2(2)}
 #IF Num_in > 2
      RVD18_1(3)  = ~
  #CASE Inv3 {~$INx3(1)} {~1.0 - $INx3(1)}
      RVD18_1(12) = ~
  #CASE INTR {~0.0} {~$INx3(2)}
 #ENDIF
 #IF Num_in > 3
      RVD18_1(4)  = ~
  #CASE Inv4 {~$INx4(1)} {~1.0 - $INx4(1)}
      RVD18_1(13) = ~
  #CASE INTR {~0.0} {~$INx4(2)}
 #ENDIF
 #IF Num_in > 4
      RVD18_1(5)  = ~
  #CASE Inv5 {~$INx5(1)} {~1.0 - $INx5(1)}
      RVD18_1(14) = ~
  #CASE INTR {~0.0} {~$INx5(2)}
 #ENDIF
 #IF Num_in > 5
      RVD18_1(6)  = ~
  #CASE Inv6 {~$INx6(1)} {~1.0 - $INx6(1)}
      RVD18_1(15) = ~
  #CASE INTR {~0.0} {~$INx6(2)}
 #ENDIF
 #IF Num_in > 6
      RVD18_1(7)  = ~
  #CASE Inv7 {~$INx7(1)} {~1.0 - $INx7(1)}
      RVD18_1(16) = ~
  #CASE INTR {~0.0} {~$INx7(2)}
 #ENDIF
 #IF Num_in > 7
      RVD18_1(8)  = ~
  #CASE Inv8 {~$INx8(1)} {~1.0 - $INx8(1)}
      RVD18_1(17) = ~
  #CASE INTR {~0.0} {~$INx8(2)}
 #ENDIF
 #IF Num_in > 8
      RVD18_1(9)  = ~
  #CASE Inv9 {~$INx9(1)} {~1.0 - $INx9(1)}
      RVD18_1(18) = ~
  #CASE INTR {~0.0} {~$INx9(2)}
 #ELSE
  #LOCAL INTEGER I_9
      DO I_9 = $Num_in1,9
        RVD18_1(I_9) = 0.0
        RVD18_1(I_9+9) = 0.0
      ENDDO
 #ENDIF
      CALL EMTDC_XLGATE($Type,$Num_in,RVD18_1,$OUTx)
!
 #IF Inv==1
      IF ( NINT( $OUTx(1) ) .NE. 0 ) THEN
          $OUTx(1) = 0.0
      ELSE
          $OUTx(1) = 1.0
      ENDIF
 #ENDIF
#ELSE
!
! Multi input ~
 #CASE Type {~AND~}{~OR~}{~XOR~}
~ gate
!
      IF (~
 #CASE Inv1 {~ ($IN1 .NE. 0) ~}{~ ($IN1 .EQ. 0) ~}
 #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
 #CASE Inv2 {~ ($IN2 .NE. 0) ~}{~ ($IN2 .EQ. 0) ~}
 #IF Num_in > 2
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv3 {~ ($IN3 .NE. 0) ~}{~ ($IN3 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 3
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv4 {~ ($IN4 .NE. 0) ~}{~ ($IN4 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 4
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv5 {~ ($IN5 .NE. 0) ~}{~ ($IN5 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 5
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv6 {~ ($IN6 .NE. 0) ~}{~ ($IN6 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 6
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv7 {~ ($IN7 .NE. 0) ~}{~ ($IN7 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 7
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv8 {~ ($IN8 .NE. 0) ~}{~ ($IN8 .EQ. 0) ~}
 #ENDIF
 #IF Num_in > 8
  #CASE Type {~.AND.~}{~.OR.~}{~.NEQV.~}
  #CASE Inv9 {~ ($IN9 .NE. 0) ~}{~ ($IN9 .EQ. 0) ~}
 #ENDIF
~) THEN
        $OUT = ~
 #CASE Inv {~1}{~0}
      ELSE
        $OUT = ~
 #CASE Inv {~0}{~1}
      ENDIF
#ENDIF
